import {useCallback, useEffect} from 'react';
import {
  computeCurrentAddOns,
  computeCurrentFont,
  filterAddOns,
  filterCompetitions,
  filterCustomizationTypes,
  filterPlayers,
  setAllAndFilteredValues,
} from '../utils/ceCustomization.utils';
export function useCEProductLoader({
  store,
  setStore,
  watchStoreChanges,
  localization,
}) {
  const loadProductCustomizationSettings = useCallback(async () => {
    const productRequestParam = store.currentProductHandle
      ? `handle=${store.currentProductHandle}`
      : store.currentProductId
      ? `id=${store.currentProductId}`
      : null;
    let apiUrl = `${
      window['customizationBffUrl'] || ''
    }/api/ce-product-customization?${productRequestParam}`;
    if (localization) {
      apiUrl = `${window['customizationBffUrl'] || ''}/${
        localization?.locale
      }-${
        localization?.market
      }/api/ce-product-customization?${productRequestParam}&country=${
        localization?.country
      }`;
    }
    setStore({isLoadingCustomization: true});
    const response = await fetch(apiUrl);
    try {
      const data = await response.json();
      if (data.error) throw new Error(data.error);
      const {
        product,
        customizationEngineSettings,
        customizationFormValidators,
        customizations,
        allCustomizationTypes,
        allFonts,
        allPlayers,
        allAddOns,
        allCompetitions,
      } = data;
      setStore({
        currentProduct: product,
        currentProductVariant: null,
        customizationEngineSettings,
        customizationFormValidators,
        isCustomizationValid: true,
      });
      const newAllCustomizations = customizations?.map((c) => ({
        value: c,
        disabled: false,
        hidden: false,
      }));
      // Validate current values against new data and apply filtering atomically
      setStore((prevStore) => {
        // Validate currentCompetition: keep if still present in new data, else fallback to first
        let validatedCompetition = prevStore.currentCompetition;
        if (
          validatedCompetition &&
          !allCompetitions?.some((c) => c.id === validatedCompetition.id)
        ) {
          validatedCompetition = null;
        }
        if (!validatedCompetition && allCompetitions?.length) {
          validatedCompetition = allCompetitions[0];
        }
        // Validate currentCustomizationType
        let validatedCustomizationName = prevStore.customizationName;
        let validatedCustomizationNumber = prevStore.customizationNumber;
        let validatedCustomizationType = prevStore.currentCustomizationType;
        if (
          validatedCustomizationType &&
          !allCustomizationTypes?.includes(validatedCustomizationType)
        ) {
          validatedCustomizationType = null;
          validatedCustomizationName = '';
          validatedCustomizationNumber = '';
        }
        // Further validate against competition (same logic as useCECompetitionEffects)
        if (validatedCustomizationType && validatedCompetition) {
          const isTypeValid = newAllCustomizations
            ?.map((c) => c.value)
            .some(
              (customization) =>
                (!customization.customizationTypes?.length ||
                  customization.customizationTypes.includes(
                    validatedCustomizationType,
                  )) &&
                (!customization.customizationCompetitions?.length ||
                  customization.customizationCompetitions?.some(
                    (comp) => comp.id === validatedCompetition?.id,
                  )),
            );
          if (!isTypeValid) {
            validatedCustomizationType = null;
            validatedCustomizationName = '';
            validatedCustomizationNumber = '';
          }
        }
        // Validate currentPlayer: keep if still present in new data and valid for competition
        let validatedPlayer = prevStore.currentPlayer;
        if (
          validatedPlayer &&
          !allPlayers?.some((p) => p.id === validatedPlayer.id)
        ) {
          validatedPlayer = null;
        }
        if (validatedPlayer && validatedCompetition) {
          const isPlayerValid =
            !validatedPlayer.competitions?.length ||
            validatedPlayer.competitions?.some(
              (comp) => comp.id === validatedCompetition?.id,
            );
          if (!isPlayerValid) {
            validatedPlayer = null;
          }
        }
        // Validate currentAddOns: keep only those present in new data
        const validatedAddOns = (prevStore.currentAddOns || []).filter(
          (addOn) => allAddOns?.some((a) => a.id === addOn.id),
        );
        // Validate currentCustomizationProduct
        let validatedCustomizationProduct =
          prevStore.currentCustomizationProduct;
        if (
          validatedCustomizationProduct &&
          !customizations?.some(
            (c) => c.id === validatedCustomizationProduct.id,
          )
        ) {
          validatedCustomizationProduct = null;
        }
        // Apply filtering with validated competition (same logic as useCECompetitionEffects)
        const competitionsFiltered = filterCompetitions({
          allCompetitions,
          currentCompetition: validatedCompetition,
        });
        const typesFiltered = filterCustomizationTypes({
          allCustomizationTypes,
          allCustomizations: newAllCustomizations || null,
          currentCompetition: validatedCompetition,
        });
        const playersFiltered = filterPlayers({
          allPlayers,
          currentCompetition: validatedCompetition,
        });
        const addOnsFiltered = filterAddOns({
          allAddOns,
          currentCompetition: validatedCompetition,
          hiddenProducts: prevStore.currentFormValidator?.hiddenProducts,
        });
        const addOnsComputed = computeCurrentAddOns({
          currentAddOns: validatedAddOns,
          allAddOns,
          currentCompetition: validatedCompetition,
        });
        const fontsFiltered = setAllAndFilteredValues({
          allValues: allFonts,
          allKey: 'allFonts',
          filteredKey: 'filteredFonts',
        });
        const validatedFont = computeCurrentFont({
          allFonts: fontsFiltered.allFonts || null,
          currentCompetition: validatedCompetition,
          currentCustomizationType: validatedCustomizationType,
        });
        return {
          allCustomizations: newAllCustomizations,
          ...competitionsFiltered,
          ...typesFiltered,
          ...playersFiltered,
          ...addOnsFiltered,
          ...fontsFiltered,
          ...addOnsComputed,
          currentCompetition: validatedCompetition,
          currentCustomizationType: validatedCustomizationType,
          currentPlayer: validatedPlayer,
          currentCustomizationProduct: validatedCustomizationProduct,
          currentFont: validatedFont,
          customizationName: validatedCustomizationName,
          customizationNumber: validatedCustomizationNumber,
        };
      });
    } catch (error) {
      console.error('Failed to load product customization settings:', error);
    } finally {
      setStore({isLoadingCustomization: false});
    }
  }, [
    store.currentProductHandle,
    store.currentProductId,
    setStore,
    localization,
  ]);
  // watch for changes in currentProductHandle/Id to reload settings
  useEffect(() => {
    if (watchStoreChanges) {
      if (store.currentProductHandle || store.currentProductId) {
        loadProductCustomizationSettings();
      }
    }
  }, [
    store.currentProductHandle,
    store.currentProductId,
    loadProductCustomizationSettings,
    watchStoreChanges,
  ]);
}
