import {useEffect} from 'react';
export function useCECustomizationTypeEffects({
  store,
  setStore,
  watchStoreChanges,
  setCurrentCompetitionById,
}) {
  // auto-select competition if only one available for the selected type
  useEffect(() => {
    if (watchStoreChanges) {
      if (store.currentCustomizationType) {
        if (store.currentCustomizationType !== 'player') {
          setStore({currentPlayer: null});
        }
        const competitions = store.allCustomizations
          ?.map((c) => c.value)
          .filter(
            (customization) =>
              !customization.customizationTypes?.length ||
              customization.customizationTypes?.includes(
                store.currentCustomizationType,
              ),
          )
          .flatMap(
            (customization) => customization.customizationCompetitions || [],
          )
          .reduce((acc, comp) => {
            if (!acc.find((c) => c.id === comp.id)) acc.push(comp);
            return acc;
          }, []);
        if (competitions && competitions.length === 1) {
          setCurrentCompetitionById(competitions[0].id);
        }
      }
    }
  }, [
    store.currentCustomizationType,
    store.allCustomizations,
    watchStoreChanges,
    setStore,
    setCurrentCompetitionById,
  ]);
  // select best customization product based on competition, type and player
  useEffect(() => {
    if (watchStoreChanges) {
      if (store.currentCompetition && store.currentCustomizationType) {
        const customizationProducts =
          store.allCustomizations?.filter(
            (customization) =>
              (!store.currentCompetition ||
                !customization.value.customizationCompetitions?.length ||
                customization.value.customizationCompetitions?.some(
                  (comp) => comp.id === store.currentCompetition?.id,
                )) &&
              ((!store.currentCustomizationType &&
                !customization.value.customizationTypes.length) ||
                customization.value.customizationTypes.includes(
                  store.currentCustomizationType,
                )) &&
              (!store.currentPlayer ||
                !customization.value.customizationPlayers?.length ||
                customization.value.customizationPlayers?.some(
                  (player) => player.id === store.currentPlayer?.id,
                )),
          ) || [];
        const customizationPoints = customizationProducts.map((_, index) => {
          const p = customizationProducts[index].value;
          let points = 0;
          if (
            p.customizationCompetitions?.some(
              (comp) => comp.id === store.currentCompetition?.id,
            )
          )
            points++;
          if (p.customizationTypes?.includes(store.currentCustomizationType))
            points++;
          if (
            p.customizationPlayers?.some(
              (player) => player.id === store.currentPlayer?.id,
            )
          )
            points++;
          return points;
        });
        const maxPoints = Math.max(...customizationPoints);
        const best = customizationProducts
          .filter((_, i) => customizationPoints[i] === maxPoints)
          // order by price ascending
          .sort((a, b) => {
            return (
              parseFloat(
                a.value.selectedOrFirstAvailableVariant?.price.amount || '0',
              ) -
              parseFloat(
                b.value.selectedOrFirstAvailableVariant?.price.amount || '0',
              )
            );
          });
        setStore({
          currentCustomizationProduct: best.length > 0 ? best[0].value : null,
        });
      } else {
        setStore({currentCustomizationProduct: null});
      }
    }
  }, [
    store.currentCompetition,
    store.currentCustomizationType,
    store.currentPlayer,
    store.allCustomizations,
    setStore,
    watchStoreChanges,
  ]);
  useEffect(() => {
    if (watchStoreChanges) {
      if (store.currentCustomizationType !== 'player') {
        setStore({
          currentPlayer: null,
          customizationName: '',
          customizationNumber: '',
        });
      }
    }
  }, [watchStoreChanges, store.currentCustomizationType, setStore]);
  // update customizationTypesPriceMap
  useEffect(() => {
    if (watchStoreChanges) {
      const customizationTypesMap = {};
      store.allCustomizations?.forEach((customization) => {
        const types =
          customization.value.customizationTypes?.length > 0
            ? customization.value.customizationTypes
            : store.allCustomizationTypes?.map((c) => c.value) || [];
        types.forEach((type) => {
          if (!customizationTypesMap[type]) {
            customizationTypesMap[type] = [];
          }
          customizationTypesMap[type].push({
            disabled: customization.disabled,
            price: customization.value.selectedOrFirstAvailableVariant
              ? parseFloat(
                  customization.value.selectedOrFirstAvailableVariant.price
                    .amount,
                )
              : 0,
            compareAtPrice: customization.value.selectedOrFirstAvailableVariant
              ? parseFloat(
                  customization.value.selectedOrFirstAvailableVariant
                    .compareAtPrice?.amount || '0',
                )
              : 0,
            currencyCode: customization.value.selectedOrFirstAvailableVariant
              ? customization.value.selectedOrFirstAvailableVariant.price
                  .currencyCode
              : '',
          });
        });
      });
      const customizationTypesMapWithPrices = {};
      Object.entries(customizationTypesMap).forEach(
        ([type, customizations]) => {
          const allDisabled = customizations.every((c) => c.disabled);
          const enabledCustomizations = allDisabled
            ? customizations
            : customizations.filter((c) => !c.disabled);
          const minPrice = Math.min(
            ...enabledCustomizations.map((c) => c.price),
          );
          const minCompareAtPrice = Math.min(
            ...enabledCustomizations.map((c) => c.compareAtPrice || 0),
          );
          customizationTypesMapWithPrices[type] = {
            price: minPrice,
            compareAtPrice: minCompareAtPrice,
            amount: `${minPrice}`,
            currencyCode: enabledCustomizations[0]?.currencyCode || '',
          };
        },
      );
      setStore({customizationTypesPriceMap: customizationTypesMapWithPrices});
    }
  }, [
    store.allCustomizations,
    store.allCustomizationTypes,
    setStore,
    watchStoreChanges,
  ]);
}
