export function setAllAndFilteredValues({
  allValues,
  filteredValues,
  allKey,
  filteredKey,
  hiddenValues,
}) {
  return {
    [allKey]: allValues?.map((value) => ({
      value,
      disabled: filteredValues
        ? !filteredValues.find((fv) =>
            fv.id ? fv.id === value.id : fv === value,
          )
        : false,
      hidden: hiddenValues
        ? !!hiddenValues.find((hv) =>
            hv.id ? hv.id === value.id : hv === value,
          )
        : false,
    })),
    [filteredKey]: filteredValues || allValues,
  };
}
export function filterCompetitions({allCompetitions, currentCompetition}) {
  return setAllAndFilteredValues({
    allValues: allCompetitions,
    filteredValues: currentCompetition ? [currentCompetition] : null,
    allKey: 'allCompetitions',
    filteredKey: 'filteredCompetitions',
  });
}
export function filterCustomizationTypes({
  allCustomizationTypes,
  allCustomizations,
  currentCompetition,
}) {
  const filteredCustomizationTypes = allCustomizationTypes?.filter((type) =>
    allCustomizations
      ?.map((c) => c.value)
      .some(
        (customization) =>
          customization.customizationTypes?.includes(type) &&
          (!customization.customizationCompetitions?.length ||
            customization.customizationCompetitions?.some(
              (comp) => comp.id === currentCompetition?.id,
            )),
      ),
  );
  return setAllAndFilteredValues({
    allValues: allCustomizationTypes,
    filteredValues: filteredCustomizationTypes,
    allKey: 'allCustomizationTypes',
    filteredKey: 'filteredCustomizationTypes',
  });
}
export function filterPlayers({allPlayers, currentCompetition}) {
  const filteredPlayers = allPlayers?.filter(
    (player) =>
      !player.competitions?.length ||
      player.competitions?.some((comp) => comp.id === currentCompetition?.id),
  );
  return setAllAndFilteredValues({
    allValues: allPlayers,
    filteredValues: filteredPlayers,
    allKey: 'allPlayers',
    filteredKey: 'filteredPlayers',
  });
}
export function filterAddOns({allAddOns, currentCompetition, hiddenProducts}) {
  const hiddenAddOnIds = hiddenProducts?.map((p) => p.id) || [];
  const filteredAddOns = allAddOns?.filter(
    (addOn) =>
      !hiddenAddOnIds?.includes(addOn.id) &&
      (!addOn.customizationCompetitions?.length ||
        addOn.customizationCompetitions?.some(
          (comp) => comp.id === currentCompetition?.id,
        )),
  );
  return setAllAndFilteredValues({
    allValues: allAddOns,
    filteredValues: filteredAddOns,
    allKey: 'allAddOns',
    filteredKey: 'filteredAddOns',
    hiddenValues: hiddenProducts,
  });
}
export function computeCurrentAddOns({
  currentAddOns,
  allAddOns,
  currentCompetition,
}) {
  const requiredAddOns = allAddOns?.filter(
    (addOn) =>
      addOn.customizationAddOnRequired &&
      (!addOn.customizationCompetitions?.length ||
        addOn.customizationCompetitions?.some(
          (comp) => comp.id === currentCompetition?.id,
        )),
  );
  const mergedAddOns = [
    ...(currentAddOns || []).filter(
      (ca) =>
        !ca.customizationCompetitions?.length ||
        ca.customizationCompetitions?.some(
          (comp) => comp.id === currentCompetition?.id,
        ),
    ),
    ...(requiredAddOns || []),
  ].reduce((acc, addOn) => {
    if (!acc.find((a) => a.id === addOn.id))
      acc.push(allAddOns?.find((a) => a.id === addOn.id) || addOn);
    return acc;
  }, []);
  return {currentAddOns: mergedAddOns};
}
export function computeCurrentFont({
  allFonts,
  currentCompetition,
  currentCustomizationType,
}) {
  return allFonts
    ?.map((font) => font.value)
    .find(
      (font) =>
        (!font.customizationTypes?.length ||
          font.customizationTypes?.includes(currentCustomizationType)) &&
        (!font.competitions?.length ||
          font.competitions?.some(
            (comp) => comp.id === currentCompetition?.id,
          )),
    );
}
