import {useEffect} from 'react';
export function useCEValidations({store, setStore}) {
  // Banned words validation
  useEffect(() => {
    const bannedWords = store.customizationEngineSettings?.bannedWords ?? [];
    if (!bannedWords.length || !store.customizationName) {
      setStore({validationErrors: []});
      return;
    }
    const upperName = store.customizationName.toUpperCase();
    const hasBannedWord = bannedWords.some(
      (word) => upperName === word.toUpperCase(),
    );
    if (hasBannedWord) {
      setStore({
        validationErrors: ['banned_word'],
      });
    } else {
      setStore(({validationErrors}) => {
        return {
          validationErrors: validationErrors.filter(
            (error) => error !== 'banned_word',
          ),
        };
      });
    }
  }, [
    store.customizationName,
    store.customizationEngineSettings?.bannedWords,
    store.currentCustomizationType,
    setStore,
  ]);
  useEffect(() => {
    switch (store.currentCustomizationType) {
      case 'player':
        if (!store.currentPlayer) {
          setStore(({validationErrors}) => ({
            validationErrors: [...validationErrors, 'missing_player'].filter(
              (error, index, self) => self.indexOf(error) === index,
            ),
          }));
        } else {
          setStore(({validationErrors}) => ({
            validationErrors: validationErrors.filter(
              (error) => error !== 'missing_player',
            ),
          }));
        }
        break;
      case 'name_and_number':
        if (!store.customizationName && !store.customizationNumber) {
          setStore(({validationErrors}) => ({
            validationErrors: [
              ...validationErrors,
              'missing_name_and_number',
            ].filter((error, index, self) => self.indexOf(error) === index),
          }));
        } else {
          setStore(({validationErrors}) => ({
            validationErrors: validationErrors.filter(
              (error) => error !== 'missing_name_and_number',
            ),
          }));
        }
        break;
      case 'number':
        if (!store.customizationNumber) {
          setStore(({validationErrors}) => ({
            validationErrors: [...validationErrors, 'missing_number'].filter(
              (error, index, self) => self.indexOf(error) === index,
            ),
          }));
        } else {
          setStore(({validationErrors}) => ({
            validationErrors: validationErrors.filter(
              (error) => error !== 'missing_number',
            ),
          }));
        }
        break;
      default:
        break;
    }
  }, [
    store.customizationName,
    store.currentCustomizationType,
    store.customizationNumber,
    store.currentPlayer,
    store.currentProduct,
    setStore,
  ]);
  // Update isCustomizationValid based on validationErrors
  useEffect(() => {
    setStore({isCustomizationValid: store.validationErrors.length === 0});
  }, [store.validationErrors, setStore]);
}
