import {useEffect} from 'react';
import {setAllAndFilteredValues} from '../utils/ceCustomization.utils';
export function useCECustomizationsEffects({
  store,
  setStore,
  watchStoreChanges,
}) {
  useEffect(() => {
    if (watchStoreChanges) {
      setStore(({allCustomizations}) => {
        let filteredCustomizations;
        if (store.currentCustomizationProduct) {
          filteredCustomizations = allCustomizations?.filter(
            (customization) =>
              customization.value.id === store.currentCustomizationProduct?.id,
          );
        } else {
          filteredCustomizations = allCustomizations?.filter(
            (customization) => {
              const matchesCompetition =
                !store.currentCompetition ||
                !customization.value.customizationCompetitions?.length ||
                customization.value.customizationCompetitions?.some(
                  (comp) => comp.id === store.currentCompetition?.id,
                );
              const matchesCustomizationType =
                !store.currentCustomizationType ||
                !customization.value.customizationTypes?.length ||
                customization.value.customizationTypes?.some(
                  (type) => type === store.currentCustomizationType,
                );
              const matchesPlayer =
                !store.currentPlayer ||
                !customization.value.customizationPlayers?.length ||
                customization.value.customizationPlayers?.some(
                  (player) => player.id === store.currentPlayer?.id,
                );
              return (
                matchesCompetition && matchesCustomizationType && matchesPlayer
              );
            },
          );
        }
        return setAllAndFilteredValues({
          allValues:
            allCustomizations?.map((customization) => customization.value) ||
            null,
          allKey: 'allCustomizations',
          filteredValues:
            filteredCustomizations?.map(
              (customization) => customization.value,
            ) || null,
          filteredKey: 'filteredCustomizations',
        });
      });
    }
  }, [
    watchStoreChanges,
    store.currentCustomizationType,
    store.currentCompetition,
    store.currentPlayer,
    store.currentCustomizationProduct,
    setStore,
  ]);
}
