import {useEffect} from 'react';
import {
  computeCurrentAddOns,
  filterAddOns,
  filterCompetitions,
  filterCustomizationTypes,
  filterPlayers,
} from '../utils/ceCustomization.utils';
export function useCECompetitionEffects({store, setStore, watchStoreChanges}) {
  // init first available competition
  useEffect(() => {
    if (watchStoreChanges) {
      if (store.currentCompetition === null && store.allCompetitions?.length) {
        setStore({currentCompetition: store.allCompetitions[0].value});
      }
    }
  }, [
    watchStoreChanges,
    store.currentCompetition,
    store.allCompetitions,
    setStore,
  ]);
  // filter states on competition change
  useEffect(() => {
    if (watchStoreChanges) {
      setStore(({allCompetitions}) =>
        filterCompetitions({
          allCompetitions:
            allCompetitions?.map((competition) => competition.value) || null,
          currentCompetition: store.currentCompetition,
        }),
      );
      setStore(({allCustomizationTypes}) =>
        filterCustomizationTypes({
          allCustomizationTypes:
            allCustomizationTypes?.map((type) => type.value) || null,
          allCustomizations: store.allCustomizations,
          currentCompetition: store.currentCompetition,
        }),
      );
      setStore(({allAddOns, currentFormValidator}) =>
        filterAddOns({
          allAddOns: allAddOns?.map((addOn) => addOn.value) || null,
          currentCompetition: store.currentCompetition,
          hiddenProducts: currentFormValidator?.hiddenProducts,
        }),
      );
      setStore(({allPlayers}) =>
        filterPlayers({
          allPlayers: allPlayers?.map((player) => player.value) || null,
          currentCompetition: store.currentCompetition,
        }),
      );
      setStore(({currentAddOns, allAddOns}) =>
        computeCurrentAddOns({
          currentAddOns: currentAddOns || [],
          allAddOns: allAddOns?.map((addOn) => addOn.value) || null,
          currentCompetition: store.currentCompetition,
        }),
      );
    }
  }, [
    store.currentCompetition,
    store.allCustomizations,
    setStore,
    watchStoreChanges,
  ]);
  // reset player if invalid after competition change
  useEffect(() => {
    if (watchStoreChanges) {
      if (store.currentPlayer && store.currentCompetition) {
        const isPlayerValid =
          !store.currentPlayer.competitions?.length ||
          store.currentPlayer.competitions?.some(
            (comp) => comp.id === store.currentCompetition?.id,
          );
        if (!isPlayerValid) setStore({currentPlayer: null});
      }
    }
  }, [
    store.currentCompetition,
    store.currentPlayer,
    store.allCustomizations,
    watchStoreChanges,
    setStore,
  ]);
  // reset customization type if invalid after competition change
  useEffect(() => {
    if (watchStoreChanges) {
      if (store.currentCustomizationType && store.currentCompetition) {
        const isCustomizationTypeValid = store.allCustomizations
          ?.map((c) => c.value)
          .some(
            (customization) =>
              (!customization.customizationTypes?.length ||
                customization.customizationTypes.includes(
                  store.currentCustomizationType,
                )) &&
              (!customization.customizationCompetitions?.length ||
                customization.customizationCompetitions?.some(
                  (comp) => comp.id === store.currentCompetition?.id,
                )),
          );
        if (!isCustomizationTypeValid) {
          setStore({currentCustomizationType: null});
        }
      }
    }
  }, [
    store.currentCompetition,
    store.currentCustomizationType,
    store.allCustomizations,
    watchStoreChanges,
    setStore,
  ]);
}
