import {useCallback, useEffect, useRef, useState} from 'react';
import {getStore, mappedStore, notifyMappedStoreChange} from './store/ceStore';
import {useCEBundlePriceSync} from './hooks/useCEBundlePriceSync';
import {useCECompetitionCallbacks} from './hooks/useCECompetitionCallbacks';
import {useCECompetitionEffects} from './hooks/useCECompetitionEffects';
import {useCEPlayerCallbacks} from './hooks/useCEPlayerCallbacks';
import {useCEPlayerEffects} from './hooks/useCEPlayerEffects';
import {useCECustomizationTypeEffects} from './hooks/useCECustomizationTypeEffects';
import {useCEAddOnCallbacks} from './hooks/useCEAddOnCallbacks';
import {useCEAddOnEffects} from './hooks/useCEAddOnEffects';
import {useCEFontEffects} from './hooks/useCEFontEffects';
import {useCEVariantEffects} from './hooks/useCEVariantEffects';
import {useCEProductLoader} from './hooks/useCEProductLoader';
import {useCEValidations} from './hooks/useCEValidations';
import {useCECustomizationsEffects} from './hooks/useCECustomizationsEffects';
export {subscribeMappedStore, useMappedStoreChanges} from './store/ceStore';
export function useCEProductCustomization({
  storeName,
  watchStoreChanges = true,
  localization,
}) {
  if (storeName && !mappedStore[storeName]) {
    mappedStore[storeName] = getStore();
  }
  const state = useRef((storeName && mappedStore[storeName]) || getStore());
  const [store, setStoreValue] = useState(state.current.store);
  const storeUUID = useRef(storeName || Date.now());
  const currentProductRef = useRef(store.currentProduct);
  currentProductRef.current = store.currentProduct;
  const storeRef = useRef(store);
  storeRef.current = store;
  useEffect(() => {
    const unsubscribe = state.current.subscribe((newStore) => {
      setStoreValue(newStore);
      notifyMappedStoreChange(storeUUID.current.toString());
    });
    return unsubscribe;
  }, []);
  const setStore = useCallback((newStore) => {
    const updates =
      typeof newStore === 'function' ? newStore(state.current.store) : newStore;
    state.current.setStore({...state.current.store, ...updates});
  }, []);
  // sync to window.mappedStore for debug / external integrations
  useEffect(() => {
    const uuid = storeUUID.current;
    if (!window['mappedStore']) {
      window['mappedStore'] = {};
    }
    window['mappedStore'][storeUUID.current] = store;
    return () => {
      delete window['mappedStore'][uuid];
    };
  }, [storeUUID, store]);
  const resetCustomization = useCallback(() => {
    setStore({
      currentFont: null,
      currentPlayer: null,
      currentAddOns: [],
      currentCustomizationType: null,
      currentCustomizationProduct: null,
      currentCompetition: store.allCompetitions?.[0]?.value || null,
      customizationName: '',
      customizationNumber: '',
      price: 0,
      compareAtPrice: 0,
    });
  }, [setStore, store.allCompetitions]);
  useCEBundlePriceSync({store, setStore, storeUUID, currentProductRef});
  const {setCurrentCompetitionById, setCompetitionByHandle} =
    useCECompetitionCallbacks({store, setStore});
  useCECustomizationsEffects({store, setStore, watchStoreChanges});
  useCECompetitionEffects({store, setStore, watchStoreChanges});
  const {setPlayerByHandle, setPlayerBySlug} = useCEPlayerCallbacks({
    store,
    setStore,
  });
  useCEPlayerEffects({
    store,
    setStore,
    watchStoreChanges,
    setCurrentCompetitionById,
  });
  useCECustomizationTypeEffects({
    store,
    setStore,
    watchStoreChanges,
    setCurrentCompetitionById,
  });
  const {toggleAddOn, applyAllAddOns} = useCEAddOnCallbacks({
    store,
    setStore,
    setCurrentCompetitionById,
  });
  useCEAddOnEffects({store, setStore, watchStoreChanges});
  useCEFontEffects({store, setStore, watchStoreChanges});
  useCEVariantEffects({store, setStore, watchStoreChanges, storeRef});
  useCEProductLoader({
    store,
    setStore,
    watchStoreChanges,
    localization,
  });
  useCEValidations({store, setStore});
  const getStoreByName = useCallback(
    (name) => mappedStore[name]?.store || null,
    [],
  );
  return {
    store,
    setStore,
    toggleAddOn,
    setPlayerByHandle,
    setPlayerBySlug,
    setCompetitionByHandle,
    resetCustomization,
    applyAllAddOns,
    getStoreByName,
  };
}
