import {useEffect} from 'react';
import {computeCurrentFont} from '../utils/ceCustomization.utils';
export function useCEFontEffects({store, setStore, watchStoreChanges}) {
  useEffect(() => {
    if (watchStoreChanges) {
      const currentFont = computeCurrentFont({
        allFonts: store.allFonts,
        currentCompetition: store.currentCompetition,
        currentCustomizationType: store.currentCustomizationType,
      });
      setStore({currentFont});
    }
  }, [
    store.currentCustomizationType,
    store.currentCompetition,
    store.allFonts,
    setStore,
    watchStoreChanges,
  ]);
}
