import {useEffect} from 'react';
import {subscribeMappedStore} from '../store/ceStore';
export function useCEBundlePriceSync({
  store,
  setStore,
  storeUUID,
  currentProductRef,
}) {
  useEffect(() => {
    if (!store.currentProduct?.productsHandle) return;
    const unsubscribe = subscribeMappedStore(
      (changedStoreName, newMappedStore) => {
        if (changedStoreName === storeUUID.current.toString()) return;
        let bundlePrice = 0;
        let bundleCompareAtPrice = 0;
        let currencyCode = '';
        let isLoadingCustomization = undefined;
        currentProductRef.current?.productsHandle?.forEach((handle) => {
          const productStore = newMappedStore[handle]?.store;
          if (productStore) {
            currencyCode = productStore.currencyCode || '';
            bundlePrice += (productStore?.price || 0) * 1000;
            bundleCompareAtPrice += (productStore?.compareAtPrice || 0) * 1000;
            const isCustomizableProduct = productStore.currentProductHandle;
            const isLoading = !isCustomizableProduct
              ? false
              : productStore.isLoadingCustomization;
            if (
              isLoadingCustomization === undefined ||
              isLoadingCustomization === false ||
              (isLoadingCustomization === null && isLoading === true)
            ) {
              isLoadingCustomization = isLoading;
            }
          }
        });
        if (!bundleCompareAtPrice) {
          bundleCompareAtPrice = bundlePrice;
        }
        if (currentProductRef.current?.discountPercentage) {
          bundlePrice =
            bundlePrice *
            (1 - currentProductRef.current.discountPercentage / 100);
        }
        setStore({
          currencyCode,
          price: +(bundlePrice / 1000).toFixed(2),
          compareAtPrice: +(bundleCompareAtPrice / 1000).toFixed(2),
          isLoadingCustomization,
        });
      },
    );
    return unsubscribe;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [store.currentProduct?.productsHandle?.join(','), setStore]);
}
