import {useCallback} from 'react';
export function useCEAddOnCallbacks({
  store,
  setStore,
  setCurrentCompetitionById,
}) {
  const toggleAddOn = useCallback(
    (addOn) => {
      if (store.currentAddOns?.some((a) => a.id === addOn.id)) {
        const toBeRemovedAddOns = store.currentAddOns.filter((a) =>
          addOn.customizationAlsoRemoveAddOns?.includes(a.id),
        );
        setStore({
          currentAddOns: store.currentAddOns
            .filter((a) => a.id !== addOn.id)
            .filter((a) => !toBeRemovedAddOns.includes(a)),
        });
      } else {
        const currentCompetitionId =
          addOn.customizationCompetitions?.length === 1 &&
          addOn.customizationCompetitions[0].id !== store.currentCompetition?.id
            ? addOn.customizationCompetitions[0].id
            : store.currentCompetition?.id;
        setStore({
          currentAddOns: [...store.currentAddOns, addOn].filter((a) =>
            currentCompetitionId
              ? !a.customizationCompetitions.length ||
                a.customizationCompetitions?.some(
                  (comp) => comp.id === currentCompetitionId,
                )
              : true,
          ),
        });
        if (currentCompetitionId) {
          setCurrentCompetitionById(currentCompetitionId);
        }
      }
    },
    [
      store.currentAddOns,
      store.currentCompetition,
      setStore,
      setCurrentCompetitionById,
    ],
  );
  const applyAllAddOns = useCallback(() => {
    setStore({currentAddOns: store.filteredAddOns || []});
  }, [store.filteredAddOns, setStore]);
  return {toggleAddOn, applyAllAddOns};
}
