import {useEffect} from 'react';
export function useCEPlayerEffects({
  store,
  setStore,
  watchStoreChanges,
  setCurrentCompetitionById,
}) {
  // when current player changes, update name/number and auto-select competition
  useEffect(() => {
    if (watchStoreChanges) {
      if (store.currentPlayer) {
        const competitions = store.currentPlayer.competitions?.reduce(
          (acc, comp) => {
            if (!acc.find((c) => c.id === comp.id)) acc.push(comp);
            return acc;
          },
          [],
        );
        if (competitions && competitions.length === 1) {
          setCurrentCompetitionById(competitions[0].id);
        }
      }
      if (store.currentCustomizationType === 'player') {
        if (!store.currentPlayer) {
          setStore({customizationName: '', customizationNumber: ''});
        } else {
          setStore({
            customizationName: store.currentPlayer?.displayName || '',
            customizationNumber: store.currentPlayer?.number?.toString() || '',
          });
        }
      }
    }
  }, [
    store.currentPlayer,
    store.currentCustomizationType,
    watchStoreChanges,
    setStore,
    setCurrentCompetitionById,
  ]);
}
