import {useEffect} from 'react';
export function useCEVariantEffects({
  store,
  setStore,
  watchStoreChanges,
  storeRef,
}) {
  // listen to external variant:change events from prestige theme / 3rd party
  useEffect(() => {
    const handleVariantChange = (event) => {
      const variant = event.detail.variant;
      const previousVariant = event.detail.previousVariant;
      if (
        previousVariant?.id === storeRef.current.currentProductVariant?.id &&
        variant
      ) {
        setStore({currentProductVariant: variant});
      }
    };
    window.addEventListener('variant:change', handleVariantChange);
    return () =>
      window.removeEventListener('variant:change', handleVariantChange);
  }, [setStore, storeRef]);
  // when currentProductVariant changes, update currentFormValidator
  // two matching strategies:
  // 1. first option (prestige theme)
  // 2. selectedOptions with name "Size"
  useEffect(() => {
    if (watchStoreChanges) {
      const formValidator = store.customizationFormValidators?.find(
        (validator) => {
          return (
            validator.size?.label?.toString().toLowerCase() ===
              store.currentProductVariant?.options?.[0]?.toLowerCase() ||
            validator.size?.label?.toString().toLowerCase() ===
              store.currentProductVariant?.selectedOptions
                ?.find((opt) =>
                  ['size', 'size_id'].includes(opt.name?.toLowerCase()),
                )
                ?.value.toLowerCase()
          );
        },
      );
      setStore(
        ({
          currentAddOns,
          customizationEngineSettings,
          currentCustomizationType,
        }) => ({
          currentFormValidator: formValidator,
          currentAddOns: currentAddOns?.filter(
            (addOn) =>
              !formValidator?.hiddenProducts?.some((hp) => hp.id === addOn.id),
          ),
          ...(currentCustomizationType !== 'player' && {
            customizationName: store.customizationName.slice(
              0,
              formValidator?.maxNameChars ||
                customizationEngineSettings?.defaultMaxNameChars ||
                Infinity,
            ),
          }),
          ...(currentCustomizationType !== 'player' && {
            customizationNumber: store.customizationNumber.slice(
              0,
              formValidator?.maxNumberChars ||
                customizationEngineSettings?.defaultMaxNumberChars ||
                Infinity,
            ),
          }),
        }),
      );
    }
  }, [
    store.customizationFormValidators,
    store.currentProductVariant,
    store.customizationName,
    store.customizationNumber,
    setStore,
    watchStoreChanges,
  ]);
  // price calculation: base price from variant + add-ons + customization product
  useEffect(() => {
    if (store.currentProduct && store.currentProductVariant) {
      let price =
        +store.currentProductVariant.price?.amount ||
        store.currentProductVariant.price / 100 || // product variant from prestige theme
        0;
      let compareAtPrice =
        +store.currentProductVariant.compareAtPrice?.amount ||
        +store.currentProductVariant.compare_at_price / 100 || // product variant from prestige theme
        +store.currentProductVariant.price?.amount ||
        +store.currentProductVariant.price / 100 ||
        0;
      store.currentAddOns.forEach((addOn) => {
        price += +(addOn?.selectedOrFirstAvailableVariant?.price?.amount || 0);
        compareAtPrice += +(
          addOn?.selectedOrFirstAvailableVariant?.compareAtPrice?.amount ||
          addOn?.selectedOrFirstAvailableVariant?.price?.amount ||
          0
        );
      });
      if (store.currentCustomizationProduct) {
        price += +(
          store.currentCustomizationProduct?.selectedOrFirstAvailableVariant
            ?.price?.amount || 0
        );
        compareAtPrice += +(
          store.currentCustomizationProduct?.selectedOrFirstAvailableVariant
            ?.compareAtPrice?.amount ||
          store.currentCustomizationProduct?.selectedOrFirstAvailableVariant
            ?.price?.amount ||
          0
        );
      }
      setStore({
        price,
        compareAtPrice,
        currencyCode: store.currentProductVariant?.price?.currencyCode || null,
      });
    }
  }, [
    store.currentProduct,
    store.currentProductVariant,
    store.currentCustomizationProduct,
    store.currentAddOns,
    setStore,
  ]);
}
