import {useEffect, useRef, useState} from 'react';
import ceVersion from '../ce-version.json';
export const mappedStore = {};
const mappedStoreListeners = new Set();
export function subscribeMappedStore(callback) {
  mappedStoreListeners.add(callback);
  return () => {
    mappedStoreListeners.delete(callback);
  };
}
export function notifyMappedStoreChange(changedStoreName) {
  const snapshot = {...mappedStore};
  for (const callback of mappedStoreListeners) {
    callback(changedStoreName, snapshot);
  }
}
export function useMappedStoreChanges(onMappedStoreChange) {
  const [snapshot, setSnapshot] = useState({...mappedStore});
  const onMappedStoreChangeRef = useRef(onMappedStoreChange);
  onMappedStoreChangeRef.current = onMappedStoreChange;
  useEffect(() => {
    const unsubscribe = subscribeMappedStore(
      (changedStoreName, newMappedStore) => {
        setSnapshot(newMappedStore);
        onMappedStoreChangeRef.current?.(changedStoreName, newMappedStore);
      },
    );
    return unsubscribe;
  }, []);
  return snapshot;
}
export function getStore() {
  return {
    store: {
      // all states
      allCustomizations: null,
      allCustomizationTypes: null,
      allFonts: null,
      allPlayers: null,
      allAddOns: null,
      allCompetitions: null,
      // current states
      currentCustomizationProduct: null,
      currentFont: null,
      currentPlayer: null,
      currentAddOns: [],
      currentCompetition: null,
      currentCustomizationType: null,
      currentFormValidator: null,
      // filtered states
      filteredAddOns: null,
      filteredPlayers: null,
      filteredFonts: null,
      filteredCustomizationTypes: null,
      filteredCompetitions: null,
      customizationName: '',
      customizationNumber: '',
      currentProductHandle: null,
      currentProductId: null,
      currentProduct: null,
      currentProductVariant: null,
      isLoadingCustomization: null,
      validationErrors: [],
      storeInfo: ceVersion,
    },
    listeners: new Set(),
    setStore(newStore) {
      this.store = newStore;
      this.notify();
    },
    subscribe(callback) {
      this.listeners.add(callback);
      return () => this.listeners.delete(callback);
    },
    notify() {
      for (const callback of this.listeners) {
        callback(this.store);
      }
    },
  };
}
