import {useCallback} from 'react';
export function useCECompetitionCallbacks({store, setStore}) {
  const setCurrentCompetitionById = useCallback(
    (competitionId) => {
      const competition = store.allCompetitions?.find(
        (comp) => comp.value.id === competitionId,
      );
      setStore({currentCompetition: competition?.value || null});
    },
    [store.allCompetitions, setStore],
  );
  const setCompetitionByHandle = useCallback(
    (competitionHandle) => {
      if (store.allCompetitions) {
        const competition =
          store.allCompetitions?.find(
            (c) => c.value.handle === competitionHandle,
          )?.value || null;
        if (competition) {
          setStore({currentCompetition: competition});
        }
      }
    },
    [store.allCompetitions, setStore],
  );
  return {setCurrentCompetitionById, setCompetitionByHandle};
}
