import {useEffect, useRef} from 'react';
import {setAllAndFilteredValues} from '../utils/ceCustomization.utils';
export function useCEAddOnEffects({store, setStore, watchStoreChanges}) {
  const previousAddOnsRef = useRef([]);
  // update hidden add-ons when formValidator changes
  useEffect(() => {
    if (watchStoreChanges) {
      setStore(({currentAddOns, allAddOns, currentCompetition}) => {
        const hiddenAddOnIds =
          store.currentFormValidator?.hiddenProducts?.map((p) => p.id) || [];
        const filteredAddOns = allAddOns
          ?.map((addOn) => addOn.value)
          .filter(
            (addOn) =>
              !hiddenAddOnIds?.includes(addOn.id) &&
              (!addOn.customizationCompetitions?.length ||
                currentCompetition?.id ===
                  addOn.customizationCompetitions?.[0]?.id),
          );
        return {
          ...setAllAndFilteredValues({
            allValues: allAddOns?.map((addOn) => addOn.value) || null,
            allKey: 'allAddOns',
            filteredValues: filteredAddOns,
            filteredKey: 'filteredAddOns',
            hiddenValues: store.currentFormValidator?.hiddenProducts,
          }),
          currentAddOns: currentAddOns?.filter(
            (addOn) => !(hiddenAddOnIds?.includes(addOn.id) ?? false),
          ),
        };
      });
    }
  }, [store.currentFormValidator, setStore, watchStoreChanges]);
  // manage also-add / also-remove / required add-ons on currentAddOns change
  useEffect(() => {
    if (watchStoreChanges) {
      const previousAddOns = previousAddOnsRef.current;
      const currentAddOns = store.currentAddOns || [];
      const removedAddOns = previousAddOns.filter(
        (prev) => !currentAddOns.find((a) => a.id === prev.id),
      );
      const addOnIdsToRemove = new Set();
      removedAddOns.forEach((removed) => {
        removed.customizationAlsoRemoveAddOns?.forEach((id) =>
          addOnIdsToRemove.add(id),
        );
      });
      if (addOnIdsToRemove.size > 0) {
        const filtered = currentAddOns.filter(
          (a) => !addOnIdsToRemove.has(a.id),
        );
        if (filtered.length !== currentAddOns.length) {
          previousAddOnsRef.current = filtered;
          setStore({currentAddOns: filtered});
          return;
        }
      }
      previousAddOnsRef.current = currentAddOns;
      const alsoAddIds = currentAddOns.flatMap(
        (addOn) => addOn.customizationAlsoAddAddOns || [],
      );
      if (alsoAddIds.length > 0) {
        const toAdd = store.allAddOns
          ?.map((a) => a.value)
          .filter((a) => alsoAddIds.includes(a.id));
        const newAddOns = [...currentAddOns];
        toAdd?.forEach((addOn) => {
          if (!newAddOns.find((a) => a.id === addOn.id)) newAddOns.push(addOn);
        });
        if (newAddOns.length !== currentAddOns.length) {
          previousAddOnsRef.current = newAddOns;
          setStore({currentAddOns: newAddOns});
        }
      }
      const requiredAddOns = store.allAddOns
        ?.map((a) => a.value)
        .filter(
          (addOn) =>
            addOn.customizationAddOnRequired &&
            (!addOn.customizationCompetitions?.length ||
              addOn.customizationCompetitions?.some(
                (comp) => comp.id === store.currentCompetition?.id,
              )),
        );
      const missing = requiredAddOns?.filter(
        (addOn) => !currentAddOns.find((a) => a.id === addOn.id),
      );
      if (missing && missing.length > 0) {
        const updated = [...currentAddOns, ...missing];
        previousAddOnsRef.current = updated;
        setStore({currentAddOns: updated});
      }
    }
  }, [
    store.currentAddOns,
    store.allAddOns,
    store.currentCompetition,
    setStore,
    watchStoreChanges,
  ]);
}
