import {useCallback} from 'react';
export function useCEPlayerCallbacks({store, setStore}) {
  const setPlayerByHandle = useCallback(
    (handle) => {
      if (store.filteredPlayers) {
        const player = store.filteredPlayers.find((p) => p.handle === handle);
        if (player) {
          setStore({
            currentCustomizationType: 'player',
            currentPlayer: player,
          });
        } else {
          console.error(
            'Player with handle ' +
              handle +
              ' not found in filtered players list',
          );
        }
      }
    },
    [store.filteredPlayers, setStore],
  );
  const setPlayerBySlug = useCallback(
    (slug) => {
      if (store.filteredPlayers) {
        const player = store.filteredPlayers.find((p) => p.playerSlug === slug);
        if (player) {
          setStore({
            currentCustomizationType: 'player',
            currentPlayer: player,
          });
        } else {
          console.error(
            'Player with slug ' + slug + ' not found in filtered players list',
          );
        }
      }
    },
    [store.filteredPlayers, setStore],
  );
  return {setPlayerByHandle, setPlayerBySlug};
}
